input.command:
cd assets/fonts && node -e '
const fs=require("fs");
const css=fs.readFileSync("/tmp/opencode/fonts.css","utf8");
const blocks=[...css.matchAll(/@font-face\s*{([^}]*)}/g)].map(m=>m[1]);
const keep=[];
for(const b of blocks){
  const fam=(b.match(/font-family:\s*\x27([^\x27]+)/)||[])[1];
  const style=(b.match(/font-style:\s*(\w+)/)||[])[1];
  const weight=(b.match(/font-weight:\s*(\d+)/)||[])[1];
  const url=(b.match(/url\((https:[^)]+woff2)\)/)||[])[1];
  const range=(b.match(/unicode-range:\s*([^;]+)/)||[])[1]||"";
  const isLatin=range.includes("U+0000-00FF");
  const isLatinExt=range.includes("U+0100-02BA");
  if(!isLatin&&!isLatinExt) continue;
  if(fam==="Cormorant Garamond" && !(["600","700"].includes(weight)&&style==="normal"||weight==="500"&&style==="italic")) continue;
  if(fam==="Manrope" && !["400","500","600","700","800"].includes(weight)) continue;
  const slug=`${fam.replace(/ /g,"")}-${weight}-${style}-${isLatin?"latin":"latinext"}.woff2`;
  if(keep.some(k=>k.slug===slug)) continue;
  keep.push({fam,style,weight,url,slug});
}
let out="";
for(const k of keep){
  out+=`@font-face{font-family:\x27${k.fam}\x27;font-style:${k.style};font-weight:${k.weight};font-display:swap;src:url(\x27./assets/fonts/${k.slug}\x27) format(\x27woff2\x27);}\n`;
}
fs.writeFileSync("assets-fonts.css",out);
fs.writeFileSync("/tmp/opencode/fontlist.txt",keep.map(k=>k.slug+" "+k.url).join("\n"));
console.log(out);
'

