  addPath(ctx, 0, 20, 0, 50, 7.5);
  addPath(ctx, 20, -10, 30, -14, 5);
  addPath(ctx, 20, 14, 30, 17, 5);
  addPath(ctx, -20, 8, -30, 16, 5.5);
  addPath(ctx, -26, 0, -27, -26, 4.5);
  addPath(ctx, -27, -26, -30, -30, 4);
  addPath(ctx, -26, 4, -46, 16, 5);
  addPath(ctx, -46, 16, -58, 18, 5);
  addPath(ctx, 30, -14, 48, -22, 5);
  addPath(ctx, 48, -22, 56, -24, 5);
  addPath(ctx, 0, -32, 0, -50, 5);
  addPath(ctx, 0, -50, -8, -61, 4.5);
  addPath(ctx, 8, -50, 28, -50, 4);
  addPath(ctx, -8, 20, -20, 28, 5);
  addPath(ctx, -8, 8, -12, 26, 4.5);
  addPath(ctx, 30, 17, 44, 30, 4);
  addPath(ctx, -46, 16, -50, 30, 4);

  // promenade boardwalk
  const promenade = new THREE.Mesh(new THREE.BoxGeometry(112, 0.08, 8), mat('#cbb28a', 0.95));
  promenade.position.set(0, 0.02, 52);
  promenade.receiveShadow = true;
  ctx.groundGroup.add(promenade);

  // beach
  const sand = new THREE.Mesh(new THREE.PlaneGeometry(150, 46), new THREE.MeshStandardMaterial({ map: sandTexture(), color: '#e6d2ab', roughness: 1 }));
  sand.rotation.x = -Math.PI / 2;
  sand.position.set(0, -0.01, 79);
  sand.receiveShadow = true;
  ctx.groundGroup.add(sand);

  // sea
  const water = makeWater('#2f7f8c', '#8dc4c4', 0.0);
  const sea = new THREE.Mesh(new THREE.PlaneGeometry(680, 380), water);
  sea.rotation.x = -Math.PI / 2;
  sea.position.set(0, -0.38, 285);
  ctx.groundGroup.add(sea);
  ctx.waterMats.push(water);

  const foam = new THREE.Mesh(
    new THREE.PlaneGeometry(150, 3.2),
    new THREE.MeshBasicMaterial({ color: '#f5f3e8', transparent: true, opacity: 0.4, depthWrite: false })
  );
  foam.rotation.x = -Math.PI / 2;
  foam.position.set(0, 0.005, 100.5);
  ctx.groundGroup.add(foam);
  ctx.foam = foam;

  // distant hills and island
  const hillMat = mat('#7c8557', 1);
  for (let i = 0; i < 8; i++) {
    const hill = new THREE.Mesh(new THREE.SphereGeometry(rr(18, 34), 14, 10), hillMat);
    hill.position.set(-110 + i * 32 + rr(-8, 8), rr(-9, -2), -175 + rr(-20, 10));
    hill.scale.set(rr(1.1, 1.7), rr(0.5, 0.75), 1);
    ctx.groundGroup.add(hill);
  }
  for (let i = 0; i < 3; i++) {
    const island = new THREE.Mesh(new THREE.SphereGeometry(rr(22, 40), 12, 8), mat('#6f7b58', 1));
    island.position.set(rr(-180, 180), rr(-8, -3), 300 + rr(-30, 40));
    island.scale.set(rr(1.5, 2.4), rr(0.15, 0.3), 1);
    ctx.groundGroup.add(island);
  }

  // little distant town silhouette
  for (let i = 0; i < 16; i++) {
    const h = rr(5, 12);
    const b = new THREE.Mesh(new THREE.BoxGeometry(rr(4, 9), h, rr(4, 8)), mat(pickColor(), 0.95));
    b.position.set(rr(-92, 92), h / 2, -112 + rr(-18, 8));
    ctx.groundGroup.add(b);
    const r = new THREE.Mesh(new THREE.ConeGeometry(rr(3, 6), rr(2, 3.4), 4), mat('#a35a3c', 0.95));
    r.position.set(b.position.x, h + 1, b.position.z);
    r.rotation.y = Math.PI / 4;
    ctx.groundGroup.add(r);
  }
}

function pickColor() {
  const palette = ['#d8bb92', '#e2c9a4', '#c99c74', '#e8d4b5', '#c8a07d', '#dbb894'];
  return palette[Math.floor(rnd() * palette.length)];
}

export function addPath(ctx, x1, z1, x2, z2, width = 5) {
  const len = Math.hypot(x2 - x1, z2 - z1);
  const angle = Math.atan2(x2 - x1, z2 - z1);
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(width, 0.05, len), ctx.materials.path);
  mesh.position.set((x1 + x2) / 2, 0.012, (z1 + z2) / 2);
  mesh.rotation.y = angle;
  mesh.receiveShadow = true;
  ctx.groundGroup.add(mesh);
  return mesh;
}

export function makeWater(deep = '#2f7f8c', light = '#8dc4c4', y = -0.2) {
  const uniforms = {
    uTime: { value: 0 },
    uDeep: { value: new THREE.Color(deep) },
    uLight: { value: new THREE.Color(light) },
    uSunColor: { value: new THREE.Color('#ffd9a0') },
    uSunGlow: { value: 0.8 },
    uFogColor: { value: new THREE.Color('#d8e6e4') },
    uFogNear: { value: 60 },
    uFogFar: { value: 260 }
  };
  const mat = new THREE.ShaderMaterial({
    uniforms, transparent: false, fog: false,
    vertexShader: `
      varying vec3 vWorld;
      varying vec2 vUv;
      void main(){
        vUv = uv;
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: `
      uniform float uTime; uniform vec3 uDeep; uniform vec3 uLight; uniform vec3 uSunColor;
      uniform float uSunGlow; uniform vec3 uFogColor; uniform float uFogNear; uniform float uFogFar;
      varying vec3 vWorld; varying vec2 vUv;
      void main(){
        float w1 = sin(vWorld.x * 0.16 + uTime * 0.55) * 0.5 + 0.5;
        float w2 = sin(vWorld.z * 0.21 - uTime * 0.4 + vWorld.x * 0.05) * 0.5 + 0.5;
        float w3 = sin((vWorld.x + vWorld.z) * 0.5 + uTime * 1.1) * 0.5 + 0.5;
        float waves = w1 * 0.45 + w2 * 0.35 + w3 * 0.2;
        vec3 col = mix(uDeep, uLight, waves * 0.42);
        float glint = pow(clamp(sin(vWorld.x * 0.62 + uTime * 1.4) * sin(vWorld.z * 0.57 - uTime * 1.0), 0.0, 1.0), 14.0);
        col += uSunColor * glint * 0.55 * uSunGlow;
        float flick = pow(w3, 22.0) * 0.22;
        col += vec3(1.0, 0.94, 0.82) * flick;
        float dist = distance(cameraPosition, vWorld);
        float fog = smoothstep(uFogNear, uFogFar, dist);
        col = mix(col, uFogColor, fog);
        gl_FragColor = vec4(col, 1.0);
      }`
  });
  return mat;
}

export function updateEnvironment(ctx, hour, weather, dt, camera, playerPos) {
  const sky = sampleSky(hour);
  const u = ctx.sky.uniforms;
  u.topColor.value.copy(sky.top);
  u.horizonColor.value.copy(sky.hor);
  u.sunColor.value.copy(sky.sun);
  u.sunStrength.value = clamp(sky.sunI / 2.5, 0.06, 1.2);

  const angle = ((hour - 6) / 12) * Math.PI;
  const sunY = Math.sin(angle);
  const sunDir = new THREE.Vector3(Math.cos(angle) * 0.85, Math.max(-0.6, sunY), 0.28).normalize();
  u.sunDirection.value.copy(sunDir);

  const day = clamp(sunY, 0, 1);
  const night = 1 - clamp((sunY + 0.08) * 5.5, 0, 1);
  ctx.nightFactor = night;

  if (weather === 'rain') {
    u.topColor.value.lerp(new THREE.Color('#5b6673'), 0.55);
    u.horizonColor.value.lerp(new THREE.Color('#9aa3aa'), 0.5);
    u.sunStrength.value *= 0.2;
    sky.fog.lerp(new THREE.Color('#8b949b'), 0.5);
  } else if (weather === 'cloudy') {
    u.topColor.value.lerp(new THREE.Color('#7d94ac'), 0.35);
    u.horizonColor.value.lerp(new THREE.Color('#c2c7c8'), 0.25);
    u.sunStrength.value *= 0.55;
  }

  ctx.sunLight.position.set(sunDir.x * 100, Math.max(4, sunDir.y * 100), sunDir.z * 100);
  ctx.sunLight.target.position.set(0, 0, 0);
  if (sunY > 0.02) {
    ctx.sunLight.color.copy(sky.sun);
    ctx.sunLight.intensity = sky.sunI * (weather === 'rain' ? 0.45 : weather === 'cloudy' ? 0.7 : 1);
  } else {
    ctx.sunLight.color.set('#91a8d8');
    ctx.sunLight.intensity = 0.35 * (weather === 'rain' ? 0.4 : 1);
    ctx.sunLight.position.set(-sunDir.x * 80, 55, -sunDir.z * 80);
  }

  ctx.hemi.color.copy(sky.hemiSky);
  ctx.hemi.groundColor.copy(sky.hemiGround);
  ctx.hemi.intensity = sky.hemiI * (weather === 'rain' ? 0.8 : 1);

  ctx.scene.fog.color.copy(sky.fog);
  ctx.scene.fog.near = weather === 'rain' ? 35 : 70;
  ctx.scene.fog.far = weather === 'rain' ? 190 : 300;

  for (const w of ctx.waterMats) {
    w.uniforms.uTime.value += dt;
    w.uniforms.uFogColor.value.copy(sky.fog);
    w.uniforms.uSunGlow.value = clamp(sky.sunI / 2.4, 0.08, 1.2);
    w.uniforms.uSunColor.value.copy(sky.sun);
    w.uniforms.uFogNear.value = ctx.scene.fog.near;
    w.uniforms.uFogFar.value = ctx.scene.fog.far;
  }
  if (ctx.foam) {
    ctx.foam.material.opacity = 0.28 + Math.sin(performance.now() * 0.001) * 0.1;
  }

  ctx.sky.starMat.opacity = night * (weather === 'sunny' ? 0.9 : 0.1);
  ctx.sky.stars.visible = night > 0.05;
  ctx.windowMat.emissiveIntensity = night * 1.5;
  ctx.lampBulb.emissiveIntensity = 0.15 + night * 2.2;
  ctx.stringBulb.emissiveIntensity = 0.1 + night * 2.6;
  for (const l of ctx.lampLights) l.intensity = night * 9;
  for (const c of ctx.clouds) {
    c.visible = weather !== 'sunny';
    c.position.x += dt * 0.7;
    if (c.position.x > 200) c.position.x = -200;
    c.children.forEach((p) => { p.material.color.set(weather === 'rain' ? '#aeb6bc' : '#f7f2e9'); p.material.opacity = weather === 'rain' ? 0.5 : 0.32; });
  }
  const rain = ctx.rain;
  rain.visible = weather === 'rain';
  if (rain.visible) {
    rain.position.set(playerPos.x, 0, playerPos.z);
    const pos = rain.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      let y = pos.getY(i) - dt * 26;
      if (y < 0) y += 26;
      pos.setY(i, y);
    }
    pos.needsUpdate = true;
  }
  ctx.sky.mesh.position.copy(camera.position);
  ctx.sky.stars.position.copy(camera.position);
}

import * as THREE from 'three';
import { mat, box, addCollider, gableRoofGeometry, roofTexture, signMesh } from '../gl/helpers.js';

const frameMat = mat('#eadfc9', 0.9);
const glassFrameMat = mat('#cdbfa8', 0.85);
const doorMat = mat('#5b3c26', 0.85);
const shutterColors = ['#3f5b53', '#4e6a5b', '#6e7b58', '#7d4b3a', '#39545e', '#8a6b47'];

export function addRotatedCollider(ctx, x, z, w, d, rotY) {
  const c = Math.abs(Math.cos(rotY)), s = Math.abs(Math.sin(rotY));
  const hw = (c * w + s * d) / 2 + 0.35;
  const hd = (s * w + c * d) / 2 + 0.35;
  addCollider(ctx, x, z, hw, hd);
}

export function addWindow(group, ctx, x, y, z, ry, opts = {}) {
  const win = new THREE.Group();
  win.position.set(x, y, z);
  win.rotation.y = ry;
  const frame = box(1.0, 1.5, 0.09, frameMat);
  frame.position.z = 0.02;
  win.add(frame);
  const glass = new THREE.Mesh(new THREE.PlaneGeometry(0.82, 1.26), ctx.windowMat);
  glass.position.z = 0.075;
  win.add(glass);
  const sill = box(1.15, 0.1, 0.22, frameMat);
  sill.position.set(0, -0.8, 0.05);
  win.add(sill);
  const mid = box(0.08, 1.26, 0.05, frameMat);
  mid.position.z = 0.08;
  win.add(mid);
  if (opts.shutters !== false) {
    const sm = mat(opts.shutter || shutterColors[Math.floor(Math.random() * shutterColors.length)], 0.9);
    for (const side of [-1, 1]) {
      const sh = box(0.24, 1.34, 0.06, sm);
      sh.position.set(side * 0.63, 0, 0.03);
      win.add(sh);
    }
  }
  if (opts.flowers && Math.random() > 0.45) {
    const fb = box(1.0, 0.22, 0.24, mat('#7a5638', 0.95));
    fb.position.set(0, -0.92, 0.14);
    win.add(fb);
    for (let i = 0; i < 4; i++) {
      const f = new THREE.Mesh(new THREE.SphereGeometry(0.085, 6, 5), mat(['#c4576b', '#d9778b', '#e0a04c'][i % 3], 0.85));
      f.position.set(-0.34 + i * 0.22, -0.78, 0.18);
      win.add(f);
    }
  }
  if (opts.balcony) {
    const slab = box(2.15, 0.14, 0.82, mat('#d8c8ad', 0.9));
    slab.position.set(0, -1.0, 0.38);
    win.add(slab);
    const railMat = mat('#32352f', 0.5, 0.4);
    const top = box(2.15, 0.06, 0.06, railMat);
    top.position.set(0, -0.32, 0.76);
    win.add(top);
    for (let i = -4; i <= 4; i++) {
      const bar = box(0.035, 0.68, 0.035, railMat);
      bar.position.set(i * 0.24, -0.66, 0.76);
      win.add(bar);
    }
    if (opts.laundry) {
      const colors = ['#e8e1d3', '#c4576b', '#6f8fa5', '#e0c486'];
      for (let i = 0; i < 3; i++) {
        const cloth = box(0.42, 0.55, 0.03, mat(colors[i % colors.length], 0.9));
        cloth.position.set(-0.55 + i * 0.5, -0.55, 0.82);
        cloth.rotation.z = (i - 1) * 0.04;
        win.add(cloth);
      }
    }
  }
  group.add(win);
}

export function addDoor(group, ctx, x, z, ry, w = 1.5, h = 2.6, opts = {}) {
  const d = new THREE.Group();
  d.position.set(x, 0, z);
  d.rotation.y = ry;
  const frame = box(w + 0.35, h + 0.2, 0.16, frameMat);
  frame.position.y = h / 2;
  d.add(frame);
  const door = box(w, h, 0.1, opts.material || doorMat);
  door.position.set(0, h / 2, 0.08);
  d.add(door);
  const arch = new THREE.Mesh(new THREE.CylinderGeometry(w / 2, w / 2, 0.12, 16, 1, false, 0, Math.PI), frameMat);
  arch.rotation.x = Math.PI / 2;
  arch.rotation.z = Math.PI / 2;
  arch.position.set(0, h, 0.05);
  arch.scale.z = 0.5;
  d.add(arch);
  const handle = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), mat('#c9a45c', 0.35, 0.8));
  handle.position.set(w * 0.3, h * 0.48, 0.15);
  d.add(handle);
  const step = box(w + 0.9, 0.14, 0.7, mat('#c9bca6', 0.95));
  step.position.set(0, 0.07, 0.45);
  d.add(step);
  if (opts.lamp) {
    const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 8), ctx.lampBulb);
    lamp.position.set(w / 2 + 0.4, h + 0.05, 0.2);
    d.add(lamp);
  }
  group.add(d);
}

export function addAwning(group, ctx, x, y, z, width, rotY = 0, material = ctx.materials.awning) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  g.rotation.y = rotY;
  const awning = new THREE.Mesh(new THREE.BoxGeometry(width, 0.08, 2.8), material);
  awning.rotation.x = -0.28;
  awning.position.set(0, 0, 1.2);
  awning.castShadow = true;
  g.add(awning);
  const valance = new THREE.Mesh(new THREE.BoxGeometry(width, 0.5, 0.06), material);
  valance.position.set(0, -0.55, 2.4);
  g.add(valance);
  for (const side of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.6, 6), mat('#4a453d', 0.6, 0.4));
    arm.rotation.x = Math.PI / 2.4;
    arm.position.set(side * (width / 2 - 0.2), -0.32, 1.15);
    g.add(arm);
  }
  group.add(g);
  return g;
}

export function addBuilding(ctx, opts) {
  const {
    x, z, w = 10, d = 8, h = 9, color = '#e2c9a4', roofColor = '#b65f38',
    rotY = 0, floors = Math.max(2, Math.round(h / 3)), shutters = true,
    balconies = false, flowers = false, laundry = false, sign = null, signSub = '',
    signColor = '#f3e8d2', roofHeight = null, door = true, doorFace = 1
  } = opts;

  const group = new THREE.Group();
  group.position.set(x, 0, z);
  group.rotation.y = rotY;

  const wallMat = new THREE.MeshStandardMaterial({
    color, roughness: 0.92, map: ctx.materials.plaster
  });
  const walls = box(w, h, d, wallMat);
  walls.position.y = h / 2;
  group.add(walls);

  const base = box(w + 0.12, 0.5, d + 0.12, mat('#b8a78d', 0.95));
  base.position.y = 0.25;
  group.add(base);

  const roofMat = new THREE.MeshStandardMaterial({ color: roofColor, roughness: 0.9, map: roofTexture() });
  const roof = new THREE.Mesh(gableRoofGeometry(w, d, roofHeight || Math.max(1.8, w * 0.18)), roofMat);
  roof.position.y = h;
  roof.castShadow = true;
  roof.receiveShadow = true;
  group.add(roof);

  const chimney = box(0.7, 1.4, 0.7, mat('#c7a58a', 0.95));
  chimney.position.set(w * 0.27, h + 1.1, -d * 0.18);
  group.add(chimney);

  const floorH = h / floors;
  for (let f = 0; f < floors; f++) {
    const y = f * floorH + floorH * 0.55;
    if (f === 0) continue;
    const count = Math.max(2, Math.floor(w / 2.6));
    for (let i = 0; i < count; i++) {
      const px = -w / 2 + (w / (count + 1)) * (i + 1);
      const bal = balconies && f === 1 && i % 2 === 0;
      addWindow(group, ctx, px, y, d / 2 + 0.05, 0, { shutters, flowers, balcony: bal, laundry: bal && laundry });
      if (w > 7) addWindow(group, ctx, px, y, -d / 2 - 0.05, Math.PI, { shutters, flowers: false });
    }
    if (w > 8) {
      const sideCount = Math.max(2, Math.floor(d / 3));
      for (const side of [-1, 1]) {
        for (let i = 0; i < sideCount; i++) {
          const pz = -d / 2 + (d / (sideCount + 1)) * (i + 1);
          addWindow(group, ctx, side * (w / 2 + 0.05), y, pz, side * Math.PI / 2, { shutters, flowers: false });
        }
      }
    }
  }

  // ground floor windows
  const groundCount = Math.max(2, Math.floor(w / 3.4));
  for (let i = 0; i < groundCount; i++) {
    const px = -w / 2 + (w / (groundCount + 1)) * (i + 1);
    if (door && Math.abs(px) < 1.4) continue;
    addWindow(group, ctx, px, 1.75, d / 2 + 0.05, 0, { shutters, flowers, balcony: false });
  }

  if (door) {
    const doorOffset = doorFace === 0 ? 0 : w * 0.26;
    addDoor(group, ctx, doorOffset, d / 2 + 0.04, 0, 1.4, 2.5, { lamp: true });
  }

  if (sign) {
    const s = signMesh(sign, { bg: signColor, sub: signSub }, Math.min(w - 2, 5.4), signSub ? 1.7 : 0.95);
    s.position.set(0, h + 0.02, d / 2 + 0.1);
    s.rotation.x = -0.05;
    // place sign against facade just above the door
    s.position.set(doorFace === 0 ? 0 : w * 0.26, 2.95, d / 2 + 0.12);
    group.add(s);
  }

  ctx.cityGroup.add(group);
  addRotatedCollider(ctx, x, z, w, d, rotY);
  return group;
}

export function tableSet(ctx, x, z, rotY = 0, umbrella = false) {
  const g = new THREE.Group();
  const metal = mat('#4c4a44', 0.55, 0.4);
  const top = new THREE.Mesh(new THREE.CylinderGeometry(0.62, 0.62, 0.06, 16), mat('#e7dcc8', 0.8));
  top.position.y = 0.75;
  top.castShadow = true;
  g.add(top);
  const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.75, 8), metal);
  leg.position.y = 0.38;
  g.add(leg);
  const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.34, 0.05, 12), metal);
  foot.position.y = 0.03;
  g.add(foot);
  for (const s of [-1, 1]) {
    const chair = new THREE.Group();
    chair.position.set(s * 0.98, 0, 0);
    chair.rotation.y = s * Math.PI / 2;
    const seat = box(0.5, 0.06, 0.5, ctx.materials.wood);
    seat.position.y = 0.46;
    chair.add(seat);
    const back = box(0.5, 0.55, 0.05, ctx.materials.wood);
    back.position.set(0, 0.73, -0.22);
    chair.add(back);
    for (const cs of [-1, 1]) for (const cz of [-1, 1]) {
      const l = box(0.04, 0.46, 0.04, metal);
      l.position.set(cs * 0.2, 0.23, cz * 0.2);
      chair.add(l);
    }
    g.add(chair);
  }
  if (umbrella) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 2.5, 8), metal);
    pole.position.y = 1.25;
    g.add(pole);
    const can = new THREE.Mesh(new THREE.ConeGeometry(1.8, 0.6, 10), mat('#efe4cf', 0.9));
    can.position.y = 2.5;
    can.castShadow = true;
    g.add(can);
  }
  g.position.set(x, 0, z);
  g.rotation.y = rotY;
  ctx.cityGroup.add(g);
  return g;
}

export function addStringLights(ctx, p1, p2, sag = 1.4, count = 16) {
  const a = new THREE.Vector3(p1[0], p1[1], p1[2]);
  const b = new THREE.Vector3(p2[0], p2[1], p2[2]);
  const mid = a.clone().lerp(b, 0.5);
  mid.y -= sag;
  const curve = new THREE.QuadraticBezierCurve3(a, mid, b);
  const points = curve.getPoints(40);
  const wire = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), new THREE.LineBasicMaterial({ color: '#2d2d2a' }));
  ctx.cityGroup.add(wire);
  for (let i = 1; i < count; i++) {
    const p = curve.getPoint(i / count);
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), ctx.stringBulb);
    bulb.position.copy(p);
    ctx.cityGroup.add(bulb);
  }
}

import * as THREE from 'three';
import { mat, box, cylinder, addCollider, bench, lampPost, signMesh } from './helpers.js';
import { addBuilding, addDoor, addAwning, tableSet, addStringLights } from './building.js';

export function buildFountain(ctx) {
  const g = new THREE.Group();
  g.position.set(0, 0, 0);
  const stone = mat('#cfc3ab', 0.92);
  const darkStone = mat('#b6a98f', 0.94);

  const basin = cylinder(4.2, 4.35, 0.85, stone, 40);
  basin.position.y = 0.42;
  g.add(basin);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(4.25, 0.16, 10, 48), darkStone);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.88;
  rim.castShadow = true;
  g.add(rim);

  const water = new THREE.Mesh(
    new THREE.CircleGeometry(3.95, 40),
    new THREE.MeshPhysicalMaterial({ color: '#6fb9bd', roughness: 0.12, metalness: 0.05, transparent: true, opacity: 0.88, transmission: 0.25 })
  );
  water.rotation.x = -Math.PI / 2;
  water.position.y = 0.74;
  g.add(water);

  const coins = new THREE.Group();
  for (let i = 0; i < 20; i++) {
    const c = new THREE.Mesh(new THREE.CircleGeometry(0.07, 8), mat('#d9b25f', 0.3, 0.8));
    c.rotation.x = -Math.PI / 2;
    const a = Math.random() * Math.PI * 2, r = Math.random() * 3.2;
    c.position.set(Math.cos(a) * r, 0.755, Math.sin(a) * r);
    coins.add(c);
  }
  g.add(coins);

  const pedestal = cylinder(0.95, 1.2, 1.3, stone, 20);
  pedestal.position.y = 1.35;
  g.add(pedestal);
  const bowl = cylinder(1.9, 0.4, 0.32, darkStone, 24);
  bowl.position.y = 2.05;
  g.add(bowl);
  const bowlWater = new THREE.Mesh(new THREE.CircleGeometry(1.78, 28), new THREE.MeshPhysicalMaterial({ color: '#7cc6c9', roughness: 0.1, transparent: true, opacity: 0.85 }));
  bowlWater.rotation.x = -Math.PI / 2;
  bowlWater.position.y = 2.2;
  g.add(bowlWater);

  const column = cylinder(0.42, 0.55, 1.7, stone, 16);
  column.position.y = 3.05;
  g.add(column);
  const upper = cylinder(1.05, 0.32, 0.24, darkStone, 20);
  upper.position.y = 3.9;
  g.add(upper);

  // statue
  const figure = new THREE.Group();
  const statueMat = mat('#c5b99f', 0.9);
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.5, 5, 10), statueMat);
  torso.position.y = 0.55;
  torso.castShadow = true;
  figure.add(torso);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.17, 12, 10), statueMat);
  head.position.y = 1.03;
  figure.add(head);
  const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 0.55, 4, 8), statueMat);
  arm.position.set(0.32, 0.72, 0.06);
  arm.rotation.z = -0.6;
  figure.add(arm);
  const arm2 = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 0.42, 4, 8), statueMat);
  arm2.position.set(-0.25, 0.5, 0.14);
  arm2.rotation.z = 0.5;
  figure.add(arm2);
  const amphora = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), statueMat);
  amphora.position.set(0.55, 0.75, 0.12);
  amphora.scale.set(1, 1.3, 1);
  figure.add(amphora);
  const legs = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 0.55, 8), statueMat);
  legs.position.y = 0.05;
  figure.add(legs);
  figure.position.y = 4.0;
  figure.scale.setScalar(1.05);
  g.add(figure);

  // water streams
  const streamMat = new THREE.MeshPhysicalMaterial({ color: '#bfe7e8', roughness: 0.15, transparent: true, opacity: 0.55, transmission: 0.2 });
  const streams = [];
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    const start = new THREE.Vector3(Math.cos(a) * 0.85, 4.0, Math.sin(a) * 0.85);
    const mid = new THREE.Vector3(Math.cos(a) * 2.0, 2.8, Math.sin(a) * 2.0);
    const end = new THREE.Vector3(Math.cos(a) * 3.35, 0.8, Math.sin(a) * 3.35);
    const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 18, 0.035, 5, false), streamMat);
    g.add(tube);
    streams.push(tube);
  }
  ctx.fountainStreams = streams;

  ctx.cityGroup.add(g);
  addCollider(ctx, 0, 0, 3.6, 3.6);
  return g;
}

export function buildDuomo(ctx) {
  const g = new THREE.Group();
  const stone = mat('#e2d3b8', 0.92);
  const trim = mat('#cbb896', 0.9);
  const roofMat = mat('#8f5a40', 0.92);

  const body = box(20, 16, 14, stone);
  body.position.set(0, 8, -34);
  g.add(body);

  const roof = new THREE.Mesh(new THREE.ConeGeometry(12, 3.5, 4), roofMat);
  roof.rotation.y = Math.PI / 4;
  roof.position.set(0, 17.6, -34);
  roof.scale.z = 0.72;
  roof.castShadow = true;
  g.add(roof);

  // facade
  const facade = box(20.6, 17, 0.9, trim);
  facade.position.set(0, 8.5, -27.1);
  g.add(facade);

  const doorFrame = box(4.8, 6.2, 0.5, mat('#d8c7ab', 0.9));
  doorFrame.position.set(0, 3.1, -26.55);
  g.add(doorFrame);
  addDoor(g, ctx, 0, -26.4, 0, 2.5, 5.0);
  addDoor(g, ctx, -5.6, -26.4, 0, 1.5, 3.4);
  addDoor(g, ctx, 5.6, -26.4, 0, 1.5, 3.4);

  for (const px of [-8.4, -3.4, 3.4, 8.4]) {
    const pil = box(1.0, 15.5, 0.8, trim);
    pil.position.set(px, 7.75, -26.5);
    g.add(pil);
    const cap = box(1.35, 0.5, 1.1, stone);
    cap.position.set(px, 15.1, -26.5);
    g.add(cap);
  }

  // pediment
  const shape = new THREE.Shape();
  shape.moveTo(-10.5, 0); shape.lineTo(10.5, 0); shape.lineTo(0, 4.6); shape.closePath();
  const pediment = new THREE.Mesh(new THREE.ExtrudeGeometry(shape, { depth: 0.8, bevelEnabled: false }), trim);
  pediment.position.set(0, 17, -27.4);
  pediment.castShadow = true;
  g.add(pediment);

  // rose window
  const rose = new THREE.Group();
  rose.position.set(0, 12.1, -26.55);
  const glass = new THREE.Mesh(new THREE.CircleGeometry(2.25, 32), new THREE.MeshStandardMaterial({ color: '#3c4a55', emissive: '#8c5a3a', emissiveIntensity: 0.2, roughness: 0.4 }));
  rose.add(glass);
  const ring = new THREE.Mesh(new THREE.TorusGeometry(2.35, 0.16, 8, 32), trim);
  rose.add(ring);
  for (let i = 0; i < 8; i++) {
    const spoke = box(0.1, 4.4, 0.08, trim);
    spoke.rotation.z = (i / 8) * Math.PI;
    rose.add(spoke);
  }
  const inner = new THREE.Mesh(new THREE.TorusGeometry(0.75, 0.09, 6, 20), trim);
  rose.add(inner);
  g.add(rose);

  // steps
  for (let i = 0; i < 4; i++) {
    const step = box(23 - i * 1.2, 0.16, 1.2, mat('#d6c8ae', 0.95));
    step.position.set(0, 0.08 + i * 0.15, -25.4 - i * 0.9);
    step.receiveShadow = true;
    g.add(step);
  }

  // dome
  const drum = cylinder(5.2, 5.4, 3.6, stone, 28);
  drum.position.set(0, 19.2, -40);
  g.add(drum);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const win = box(0.9, 1.8, 0.3, ctx.windowMat);
    win.position.set(Math.cos(a) * 5.18, 19.3, -40 + Math.sin(a) * 5.18);
    win.rotation.y = -a + Math.PI / 2;
    g.add(win);
  }
  const dome = new THREE.Mesh(new THREE.SphereGeometry(5.3, 28, 16, 0, Math.PI * 2, 0, Math.PI / 2), mat('#c9905f', 0.88));
  dome.position.set(0, 21, -40);
  dome.castShadow = true;
  g.add(dome);
  const lantern = cylinder(0.8, 1.0, 2.2, stone, 12);
  lantern.position.set(0, 27, -40);
  g.add(lantern);
  const lanternDome = new THREE.Mesh(new THREE.SphereGeometry(0.9, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), mat('#b57a4f', 0.9));
  lanternDome.position.set(0, 28.1, -40);
  g.add(lanternDome);
  const crossV = box(0.1, 1.2, 0.1, mat('#c9a45c', 0.4, 0.7));
  crossV.position.set(0, 29.1, -40);
  g.add(crossV);
  const crossH = box(0.6, 0.1, 0.1, mat('#c9a45c', 0.4, 0.7));
  crossH.position.set(0, 29.35, -40);
  g.add(crossH);

  // bell tower
  const tower = new THREE.Group();
  const towerBase = box(5, 23, 5, stone);
  towerBase.position.y = 11.5;
  tower.add(towerBase);
  for (const side of [0, 1, 2, 3]) {
    const a = (side / 4) * Math.PI * 2;
    const opening = box(1.5, 3.2, 0.3, ctx.windowMat);
    opening.position.set(Math.sin(a) * 2.52, 18, Math.cos(a) * 2.52);
    opening.rotation.y = a;
    tower.add(opening);
  }
  const towerTop = box(6, 0.8, 6, trim);
  towerTop.position.y = 23.2;
  tower.add(towerTop);
  const towerRoof = new THREE.Mesh(new THREE.ConeGeometry(4.2, 4.4, 4), mat('#8f5a40', 0.9));
  towerRoof.position.y = 25.8;
  towerRoof.rotation.y = Math.PI / 4;
  towerRoof.castShadow = true;
  tower.add(towerRoof);
  const towerCross = box(0.08, 1.1, 0.08, mat('#c9a45c', 0.4, 0.7));
  towerCross.position.y = 29;
  tower.add(towerCross);
  tower.position.set(-13, 0, -40);
  g.add(tower);

  const plaque = signMesh('DUOMO DI SAN MARCO', { bg: '#e8dcc2', fg: '#6b5138' }, 4.6, 0.75);
  plaque.position.set(0, 6.35, -26.35);
  g.add(plaque);

  ctx.cityGroup.add(g);
  addCollider(ctx, 0, -34, 10.6, 7.4);
  addCollider(ctx, -13, -40, 3.0, 3.0);
  return g;
}

export function buildCafe(ctx) {
