  });
  addAwning(g, ctx, 0, 3.1, 6.05, 8, 0, mat('#3f4a44', 0.9));
  for (const [x, z] of [[33.2, -23.5], [33.2, -12.5]]) {
    const rack = new THREE.Group();
    for (const s of [-1, 1]) {
