      post.position.set(s * 0.55, 1.1, 0);
      rack.add(post);
    }
    const bar = box(1.4, 0.08, 0.08, mat('#2f3330', 0.6, 0.4));
    bar.position.y = 2.0;
    rack.add(bar);
    rack.position.set(x, 0, z);
    ctx.cityGroup.add(rack);
  }
  return g;
}

