export function buildTreesAndProps(ctx) {
  const cypresses = [
    [-9, 19], [9, 19], [-16, -12], [16, -12], [-24, 18], [24, 26], [-44, 6], [46, 4],
    [-36, 36], [36, 36], [-58, -8], [52, 12], [-44, -16], [40, -30], [-30, -18], [30, -8],
