11: export function createWorld(renderer, scene) {
12:   scene.fog = new THREE.Fog('#d8e6e4', 70, 300);
13:   const ctx = createContext(renderer, scene);
14:   ctx.dlcEnabled = Object.fromEntries(DLCS.map((d) => [d.id, true]));
15: 
16:   buildBase(ctx);
17:   buildMare(ctx);
18:   buildToscana(ctx);
19:   buildRoma(ctx);
20:   buildVenezia(ctx);
21:   buildModa(ctx);
22:   buildAmore(ctx);
23:   buildPets(ctx);
24:   buildNPCs(ctx);
25:   buildParticles(ctx);
26:   buildSpotMarkers(ctx);
27: 
28:   function setDLC(id, on) {
29:     ctx.dlcEnabled[id] = !!on;
30:     if (ctx.dlcGroups[id]) ctx.dlcGroups[id].visible = !!on;
31:     if (id === 'pets' && !on && ctx.pet) {
32:       ctx.pet.model.group.visible = false;
33:     } else if (id === 'pets' && on && ctx.pet) {
34:       ctx.pet.model.group.visible = true;
35:     }
36:   }
37: 
38:   function setPet(type) {
39:     if (ctx.pet) {
40:       scene.remove(ctx.pet.model.group);
41:       ctx.pet = null;
42:     }
43:     if (!type) return;
44:     const model = buildPet(type, type === 'cat' ? '#6b6b6b' : '#c79a62');
45:     model.group.visible = ctx.dlcEnabled.pets;
46:     scene.add(model.group);
47:     ctx.pet = { type, model, pos: new THREE.Vector3(0, 0, 12), phase: 0 };
48:   }
49: 
50:   function update(dt, info) {
51:     const { hour, weather, playerPos, camera, playerSpeed = 0 } = info;
52:     ctx.hour = hour;
53:     ctx.weather = weather;
54:     ctx.playerPos.copy(playerPos);
55:     updateEnvironment(ctx, hour, weather, dt, camera, playerPos);
56:     updateNPCs(ctx, dt);
57:     updatePet(ctx, dt, playerPos);
58:     updateMarkers(ctx, dt, playerPos);
59:     updateParticles(ctx, dt, hour);
60:     updateAmbientProps(ctx, dt);
61:   }
62: 
63:   return {
64:     ctx, scene, renderer,
65:     update, setDLC, setPet,
66:     isBlocked: (x, z) => blocked(ctx, x, z),
67:     spots: SPOTS,
68:     dlcs: DLCS
69:   };
70: }
