85: function buildSpotMarkers(ctx) {
86:   ctx.spotMarkers = {};
87:   for (const spot of SPOTS) {
88:     const g = new THREE.Group();
89:     g.position.set(spot.x, 0.04, spot.z);
90:     const ringMat = new THREE.MeshBasicMaterial({ color: spot.color, transparent: true, opacity: 0.65, depthWrite: false });
91:     const ring = new THREE.Mesh(new THREE.TorusGeometry(1.25, 0.055, 6, 40), ringMat);
92:     ring.rotation.x = -Math.PI / 2;
93:     ring.position.y = 0.05;
94:     g.add(ring);
95:     const ring2 = new THREE.Mesh(new THREE.RingGeometry(1.5, 1.58, 40), new THREE.MeshBasicMaterial({ color: spot.color, transparent: true, opacity: 0.2, depthWrite: false }));
96:     ring2.rotation.x = -Math.PI / 2;
97:     ring2.position.y = 0.045;
98:     g.add(ring2);
99:     const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.17, 0), new THREE.MeshBasicMaterial({ color: spot.color }));
100:     gem.position.y = 2.1;
101:     g.add(gem);
102:     const beam = new THREE.Mesh(
103:       new THREE.CylinderGeometry(0.05, 0.05, 2.1, 6),
104:       new THREE.MeshBasicMaterial({ color: spot.color, transparent: true, opacity: 0.18, depthWrite: false })
105:     );
106:     beam.position.y = 1.1;
107:     g.add(beam);
108:     const parent = spot.dlc ? ctx.dlcGroups[spot.dlc] : ctx.scene;
109:     parent.add(g);
110:     ctx.spotMarkers[spot.id] = { group: g, ring, ring2, gem, beam, color: spot.color, t: rr(0, 6) };
111:   }
112: }
