114: function updateMarkers(ctx, dt, playerPos) {
115:   for (const id in ctx.spotMarkers) {
116:     const m = ctx.spotMarkers[id];
117:     m.t += dt;
118:     m.ring.rotation.z += dt * 0.35;
119:     m.gem.rotation.y += dt * 1.2;
120:     m.gem.position.y = 2.1 + Math.sin(m.t * 1.6) * 0.12;
121:     const near = playerPos.distanceTo(m.group.position) < 8;
122:     m.ring.material.opacity = 0.45 + Math.sin(m.t * 2) * 0.12 + (near ? 0.2 : 0);
123:     m.ring2.material.opacity = near ? 0.3 : 0.12;
124:     m.gem.scale.setScalar(near ? 1.35 : 1);
125:     m.beam.material.opacity = near ? 0.3 : 0.12;
126:   }
127: }
