129: function updateNPCs(ctx, dt) {
130:   for (const npc of ctx.npcs) {
131:     if (npc.pause > 0) {
132:       npc.pause -= dt;
133:       npc.model.update(dt, 0);
134:       continue;
135:     }
136:     const target = npc.path[npc.index];
137:     const dx = target[0] - npc.pos.x;
138:     const dz = target[1] - npc.pos.z;
139:     const dist = Math.hypot(dx, dz);
140:     if (dist < 0.5) {
141:       npc.index = (npc.index + 1) % npc.path.length;
142:       npc.pause = rr(1.5, 5);
143:       continue;
144:     }
145:     const speed = 1.05;
146:     npc.pos.x += (dx / dist) * speed * dt;
147:     npc.pos.z += (dz / dist) * speed * dt;
148:     const yaw = Math.atan2(dx, dz);
149:     npc.model.group.rotation.y += (yaw - npc.model.group.rotation.y) * Math.min(1, dt * 6);
150:     npc.model.group.position.copy(npc.pos);
151:     npc.model.update(dt, speed);
152:   }
153: }
