155: function updatePet(ctx, dt, playerPos) {
156:   const pet = ctx.pet;
157:   if (!pet) return;
158:   if (!ctx.dlcEnabled.pets) return;
159:   const targetX = playerPos.x - Math.sin(ctx.playerYaw || 0) * 1.4 + 0.7;
160:   const targetZ = playerPos.z - Math.cos(ctx.playerYaw || 0) * 1.4 + 0.5;
161:   const dx = targetX - pet.pos.x, dz = targetZ - pet.pos.z;
162:   const dist = Math.hypot(dx, dz);
163:   const moving = dist > 1.6;
164:   if (moving) {
165:     const speed = Math.min(3.2, 1.6 + dist * 1.4);
166:     pet.pos.x += (dx / dist) * speed * dt;
167:     pet.pos.z += (dz / dist) * speed * dt;
168:     const yaw = Math.atan2(dx, dz);
169:     pet.model.group.rotation.y += (yaw - pet.model.group.rotation.y) * Math.min(1, dt * 8);
170:   }
171:   pet.model.group.position.set(pet.pos.x, 0, pet.pos.z);
172:   pet.model.update(dt, moving);
173:   if (ctx.shelterPets) for (const p of ctx.shelterPets) p.update(dt, false);
174: }
175: 
176: function updateAmbientProps(ctx, dt) {
177:   const t = performance.now() * 0.001;
178:   if (ctx.gondola) {
179:     ctx.gondola.position.y = 0.06 + Math.sin(t * 0.9) * 0.035;
180:     ctx.gondola.rotation.z = Math.sin(t * 0.7) * 0.012;
181:   }
182:   if (ctx.sailboat) {
183:     ctx.sailboat.position.y = 0.18 + Math.sin(t * 0.6) * 0.06;
184:     ctx.sailboat.rotation.z = Math.sin(t * 0.5) * 0.018;
185:   }
186:   if (ctx.foam) ctx.foam.position.z = 100.5 + Math.sin(t * 0.4) * 0.8;
187:   if (ctx.fountainStreams) {
188:     const o = 0.45 + Math.sin(t * 2.2) * 0.1;
189:     for (const s of ctx.fountainStreams) s.material.opacity = o;
190:   }
191: }
192: 
193: function buildParticles(ctx) {
194:   const geo = new THREE.BufferGeometry();
195:   const pts = [];
196:   for (let i = 0; i < 260; i++) {
197:     pts.push(rr(-45, 45), rr(0.4, 6), rr(-45, 45));
198:   }
199:   geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
200:   const mat = new THREE.PointsMaterial({ color: '#ffe7b0', size: 0.055, transparent: true, opacity: 0.35, depthWrite: false });
201:   const points = new THREE.Points(geo, mat);
202:   points.frustumCulled = false;
203:   ctx.scene.add(points);
204:   ctx.dust = { points, mat, base: pts.slice() };
205: }
206: 
207: function updateParticles(ctx, dt, hour) {
208:   const dust = ctx.dust;
209:   if (!dust) return;
210:   const night = ctx.nightFactor;
211:   dust.mat.opacity = 0.1 + (1 - night) * 0.28;
212:   const pos = dust.points.geometry.attributes.position;
213:   const t = performance.now() * 0.0002;
214:   for (let i = 0; i < pos.count; i++) {
215:     const bx = dust.base[i * 3];
216:     const by = dust.base[i * 3 + 1];
217:     const bz = dust.base[i * 3 + 2];
218:     pos.setX(i, bx + Math.sin(t * 4 + i) * 0.8);
219:     pos.setY(i, by + Math.sin(t * 3 + i * 0.7) * 0.4);
220:     pos.setZ(i, bz + Math.cos(t * 3.6 + i) * 0.8);
221:   }
222:   pos.needsUpdate = true;
223: }

