  for (const [x, z] of [[-62, 9], [-60.5, 9.6], [-63.5, 10.2]]) {
    const barrel = new THREE.Group();
    const body = cylinder(0.5, 0.55, 1.1, mat('#8a5a34', 0.9), 12);
    body.position.y = 0.55;
    barrel.add(body);
    for (const y of [0.3, 0.8]) {
      const band = new THREE.Mesh(new THREE.TorusGeometry(0.53, 0.035, 5, 16), ctx.materials.iron);
      band.rotation.x = Math.PI / 2;
      band.position.y = y;
      barrel.add(band);
    }
    barrel.position.set(x, 0, z);
    g.add(barrel);
  }

  tableSet(ctx, -64, 12, 0.4, true);
  for (const [x, z] of [[-52, 8], [-48, 30], [-68, 38], [-82, 35], [-56, 42]]) g.add(cypress(ctx, x, z, rr(0.9, 1.25)));
  for (const [x, z] of [[-48, 20], [-84, 26], [-40, 36]]) g.add(olive(ctx, x, z, rr(0.9, 1.2)));
  zoneSign(ctx, g, 'TOSCANA', 'vigna del sole', -52, 15, Math.PI / 2);
}

export function buildNPCs(ctx) {
  for (const n of NPCS) {
    const model = buildCharacter({
      skin: n.skin, hair: n.hair, hairStyle: n.style,
      top: n.top, bottom: n.bottom, shoes: '#3a312a', accent: '#c9a45c', scale: 0.97
    });
    model.group.position.set(n.home[0], 0, n.home[1]);
    model.group.rotation.y = Math.atan2(4 - n.home[0], 4 - n.home[1]);
    ctx.scene.add(model.group);
    ctx.npcs.push({
      ...n,
      model,
      index: 0,
      pos: new THREE.Vector3(n.home[0], 0, n.home[1]),
      walking: true,
      pause: rr(0, 2)
    });
  }
}

