const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({
    headless: false,
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const messages = [];
  page.on('console', (m) => { if (m.type() !== 'debug') messages.push(`[console:${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => messages.push(`[pageerror] ${e.stack || e.message}`));
  page.on('requestfailed', (r) => messages.push(`[requestfailed] ${r.url()} ${r.failure()?.errorText}`));

  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2200);
  await page.screenshot({ path: '/tmp/opencode/01-menu.png' });
  console.log('menu ok', await page.locator('#menu').isVisible());

  await page.click('#btn-new');
  await page.waitForTimeout(1600);
  await page.screenshot({ path: '/tmp/opencode/02-creator.png' });
  console.log('creator visible', await page.locator('#creator').isVisible());
  console.log('creator name', await page.inputValue('#cc-name'));
  console.log('creator screen classes', await page.evaluate(() => document.querySelector('#creator').className));

  await page.fill('#cc-name', 'Lucia');
  await page.click('[data-cc-tab="style"]');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/03-creator-style.png' });
  await page.click('[data-outfit="elegant"]');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/04-creator-elegant.png' });

  await page.click('#cc-begin');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: '/tmp/opencode/05-game.png' });
  console.log('game visible', await page.locator('#game').isVisible());
  console.log('HUD', await page.evaluate(() => ({
    name: localStorage.getItem('vita.save.v1') ? JSON.parse(localStorage.getItem('vita.save.v1')).name : null,
    time: document.querySelector('#hud-time')?.textContent,
    money: document.querySelector('#hud-money')?.textContent,
    quest: document.querySelector('#quest-summary')?.textContent,
    area: document.querySelector('#game-footer-loc')?.textContent,
    promptHidden: document.querySelector('#prompt')?.hidden,
    promptName: document.querySelector('#prompt-name')?.textContent,
    save: !!localStorage.getItem('vita.save.v1')
  })));

  // walk forward toward fountain and interact
  await page.keyboard.down('w');
  await page.waitForTimeout(700);
  await page.keyboard.up('w');
  await page.waitForTimeout(700);
  console.log('near prompt', await page.evaluate(() => ({
    hidden: document.querySelector('#prompt')?.hidden,
    name: document.querySelector('#prompt-name')?.textContent,
    action: document.querySelector('#prompt-action')?.textContent
  })));
  await page.keyboard.press('e');
  await page.waitForTimeout(700);
  await page.screenshot({ path: '/tmp/opencode/06-spot-modal.png' });
  console.log('modal open', await page.locator('#modal').isVisible(), await page.locator('#modal-title').textContent().catch(()=>null));

  // close and open other panels
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  await page.click('#btn-map');
  await page.waitForTimeout(700);
  await page.screenshot({ path: '/tmp/opencode/07-map.png' });
  console.log('map title', await page.locator('#modal-title').textContent().catch(()=>null));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);

  await page.click('#btn-dlc');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/08-dlc.png' });
  console.log('dlc title', await page.locator('#modal-title').textContent().catch(()=>null));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);

  await page.click('#btn-diary');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/09-diary.png' });
  console.log('diary title', await page.locator('#modal-title').textContent().catch(()=>null));
  await page.keyboard.press('Escape');

  console.log(messages.join('\n'));
  await browser.close();
})();

