const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch({
    headless: false,
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.stack || e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`[console:error] ${m.text()}`); });

  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.click('#btn-new');
  await page.waitForTimeout(800);
  await page.click('#cc-begin');
  await page.waitForTimeout(1200);
  await page.evaluate(() => window.__vita.game.setQuality('low'));

  // Place the player next to the piazza and let the prompt refresh.
  await page.evaluate(() => { const g = window.__vita.game; g.state.player.x = 0; g.state.player.z = 8; g.player.group.position.set(0, 0, 8); g.refreshPrompt(); });
  await page.waitForTimeout(250);
  console.log('prompt', await page.evaluate(() => ({ hidden: document.querySelector('#prompt').hidden, name: document.querySelector('#prompt-name').textContent, action: document.querySelector('#prompt-action').textContent })));

  await page.keyboard.press('e');
  await page.waitForTimeout(450);
  console.log('spot modal', await page.locator('#modal').isVisible(), await page.locator('#modal-title').textContent());
  console.log('spot actions', await page.evaluate(() => [...document.querySelectorAll('[data-action]')].map(b => b.dataset.action)));
  await page.screenshot({ path: '/tmp/opencode/10-spot-modal.png' });

  // Run one action
  const action = await page.locator('[data-action]').first();
  await action.click();
  await page.waitForTimeout(500);
  console.log('progress open', await page.evaluate(() => !document.querySelector('#progress').hidden), await page.locator('#progress-title').textContent().catch(()=>null));
  await page.click('#progress-skip').catch(()=>{});
  await page.waitForTimeout(1200);
  console.log('after action', await page.evaluate(() => ({ money: window.__vita.game.state.money, needs: window.__vita.game.state.needs, progress: !document.querySelector('#progress').hidden, modal: !document.querySelector('#modal').hidden })));

  // close modal if still open
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);

  // Modal screens
  async function open(btn, name) {
    await page.click(btn);
    await page.waitForTimeout(400);
    const title = await page.locator('#modal-title').textContent().catch(() => null);
    const visible = await page.locator('#modal').isVisible();
    console.log(name, visible, title);
    return { visible, title };
  }
  async function close() { await page.keyboard.press('Escape'); await page.waitForTimeout(250); }

  await open('#btn-relations', 'relations'); await close();
  await open('#btn-career', 'career'); await close();
  await open('#btn-diary', 'diary');
  console.log('quest list', await page.evaluate(() => [...document.querySelectorAll('.quest-row, .quest-item, [data-quest]')].length));
  await page.screenshot({ path: '/tmp/opencode/11-diary.png' });
  await close();
  await open('#btn-dlc', 'dlc');
  console.log('dlc toggles', await page.evaluate(() => [...document.querySelectorAll('[data-dlc-toggle]')].map(el => el.dataset.dlcToggle)));
  await close();
  await open('#btn-map', 'map'); await close();
  await open('#btn-help', 'help'); await close();
  await open('#btn-settings', 'settings');
  console.log('settings controls', await page.evaluate(() => ({
    ranges: document.querySelectorAll('[data-volume]').length,
    quality: document.querySelectorAll('[data-quality]').length,
    fullscreen: !!document.querySelector('[data-fullscreen]')
  })));
  await close();

  // Language switch via settings
  await open('#btn-settings', 'settings2');
  await page.locator('#modal-content [data-lang="en"]').click();
  await page.waitForTimeout(500);
  console.log('lang after', await page.evaluate(() => ({ lang: document.documentElement.lang, title: document.querySelector('#modal-title')?.textContent, newGame: document.querySelector('#btn-new')?.textContent?.trim(), hudDay: document.querySelector('#hud-day')?.textContent })));
  await close();

  // DLC toggle off/on from manager
  await open('#btn-dlc', 'dlc2');
  const toggle = page.locator('[data-dlc-toggle="mare"]').first();
  if (await toggle.count()) {
    await toggle.click();
    await page.waitForTimeout(600);
    console.log('mare off', await page.evaluate(() => ({ state: window.__vita.game.state.dlc.mare, visible: window.__vita.world.ctx.dlcGroups.mare.visible })));
    await toggle.click();
    await page.waitForTimeout(500);
    console.log('mare on', await page.evaluate(() => ({ state: window.__vita.game.state.dlc.mare, visible: window.__vita.world.ctx.dlcGroups.mare.visible })));
  }
  await close();

  console.log('ERRORS', errors.join('\n') || 'none');
  await browser.close();
})();

