const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: false, executablePath: '/usr/bin/chromium', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.stack || e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`[console:error] ${m.text()}`); });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1800);
  await page.screenshot({ path: '/tmp/opencode/20-mobile-menu.png' });
  console.log('menu', await page.evaluate(() => ({
    menu: !document.querySelector('#menu').hidden,
    overflow: [document.documentElement.scrollWidth, innerWidth, document.documentElement.scrollHeight, innerHeight],
    newBtn: document.querySelector('#btn-new').getBoundingClientRect().toJSON()
  })));

  await page.tap('#btn-new');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '/tmp/opencode/21-mobile-creator.png' });
  console.log('creator', await page.evaluate(() => ({
    panel: document.querySelector('.creator-panel').getBoundingClientRect().toJSON(),
    stage: document.querySelector('.creator-stage').getBoundingClientRect().toJSON(),
    scroll: [document.querySelector('.creator-panel').scrollHeight, document.querySelector('.creator-panel').clientHeight],
    begin: document.querySelector('#cc-begin').getBoundingClientRect().toJSON()
  })));

  await page.tap('#cc-begin');
  await page.waitForTimeout(1600);
  await page.evaluate(() => window.__vita.game.setQuality('low'));
  await page.screenshot({ path: '/tmp/opencode/22-mobile-game.png' });
  console.log('game', await page.evaluate(() => ({
    game: !document.querySelector('#game').hidden,
    joystick: document.querySelector('#joystick')?.getBoundingClientRect().toJSON(),
    touchInteract: document.querySelector('#touch-interact')?.getBoundingClientRect().toJSON(),
    needs: document.querySelector('.needs-panel').getBoundingClientRect().toJSON(),
    minimap: document.querySelector('.minimap-wrap').getBoundingClientRect().toJSON(),
    hudTop: document.querySelector('.hud-top').getBoundingClientRect().toJSON(),
    inner: [innerWidth, innerHeight]
  })));

  // Open a modal on mobile
  await page.tap('#btn-diary');
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/opencode/23-mobile-diary.png' });
  console.log('diary', await page.evaluate(() => ({
    visible: !document.querySelector('#modal').hidden,
    card: document.querySelector('#modal-card').getBoundingClientRect().toJSON()
  })));

  console.log('ERRORS', errors.join('\n') || 'none');
  await browser.close();
})();

