const narrow = w <= 980;
const dist = narrow ? 14.0 : 5.1;
const targetY = narrow ? 1.02 : 1.06;
const cameraY = narrow ? 1.55 : 1.62;
creatorCamera.fov = narrow ? 32 : 34;
creatorCamera.position.set(0, cameraY, dist);
