globalThis.document = { documentElement: {} };
const { setLang, t } = await import('file:///home/runner/work/PlayGround/PlayGround/js/i18n.js');
import fs from 'node:fs';
import path from 'node:path';

setLang('en');
const root = '/home/runner/work/PlayGround/PlayGround';
const files = ['index.html', ...fs.readdirSync(path.join(root, 'js')).filter(f => f.endsWith('.js')).map(f => 'js/' + f), ...fs.readdirSync(path.join(root, 'js/gl')).filter(f => f.endsWith('.js')).map(f => 'js/gl/' + f)];
const keys = new Set();
for (const f of files) {
  const src = fs.readFileSync(path.join(root, f), 'utf8');
  for (const m of src.matchAll(/\bt\(\s*['"`]([^'"`$]+)['"`]/g)) keys.add(m[1]);
  for (const m of src.matchAll(/r\(\s*['"`]([^'"`$]+)['"`]/g)) keys.add(m[1]);
  for (const m of src.matchAll(/data-i18n(?:-ph)?="([^"]+)"/g)) keys.add(m[1]);
  for (const m of src.matchAll(/data-tip="([^"]+)"/g)) keys.add(m[1]);
}
// Add dynamic prefixes from data.
const data = fs.readFileSync(path.join(root, 'js/data.js'), 'utf8');
const dlcs = [...data.matchAll(/id:\s*'([a-z]+)',\s*icon:/g)].map(m => m[1]);
const careers = [...data.matchAll(/^\s{2}([a-z]+):\s*\{\s*spot:/gm)].map(m => m[1]);
const spots = [...data.matchAll(/\{\s*id:\s*'([a-z]+)'.*?icon:/g)].map(m => m[1]);
const traits = [...data.matchAll(/^\s{2}([a-z]+):\s*\{\s*decay:/gm)].map(m => m[1]);
for (const id of dlcs) for (const k of ['name','tag','desc','f1','f2','f3']) keys.add(`dlc.${id}.${k}`);
for (const id of careers) { keys.add('c.' + id); keys.add('c.' + id + '.desc'); }
for (const id of spots) { keys.add('h.' + id); keys.add('h.' + id + '.desc'); }
for (const id of traits) { keys.add('trait.' + id); keys.add('trait.' + id + '.desc'); }
for (const k of ['sunny','cloudy','rain']) keys.add('hud.weather.' + k);
for (const k of ['energy','hunger','hygiene','social','fun']) { keys.add('need.' + k + '.short'); keys.add('need.' + k + '.low'); keys.add('need.' + k); }
for (const k of ['radiant','happy','content','tired','low','miserable']) keys.add('mood.' + k);

const missing = [];
for (const key of [...keys].sort()) {
  const v = t(key);
  if (v === undefined || v === key) missing.push(key);
}
console.log('keys', keys.size, 'missing', missing.length);
console.log(missing.join('\n'));

