const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: false, executablePath: '/usr/bin/chromium', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.stack || e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`[console:error] ${m.text()}`); });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1300);
  await page.click('#btn-new');
  await page.waitForTimeout(700);
  await page.click('#cc-begin');
  await page.waitForTimeout(1000);
  await page.evaluate(() => window.__vita.game.setQuality('low'));

  // At cafe, open spot and apply for a job via the spot career panel.
  await page.evaluate(() => { const g = window.__vita.game; g.state.player.x = 19; g.state.player.z = 5; g.player.group.position.set(19,0,5); g.refreshPrompt(); });
  await page.waitForTimeout(300);
  await page.keyboard.press('e');
  await page.waitForTimeout(400);
  console.log('cafe title', await page.locator('#modal-title').textContent());
  console.log('cafe actions', await page.evaluate(() => [...document.querySelectorAll('[data-action]')].map(b => ({ id: b.dataset.action, disabled: b.disabled }))));
  await page.click('[data-action="apply"]');
  await page.waitForTimeout(400);
  console.log('career panel', await page.locator('#modal-title').textContent());
  console.log('career options at cafe', await page.evaluate(() => [...document.querySelectorAll('[data-career]')].map(b => ({ id: b.dataset.career, disabled: b.disabled }))));
  await page.click('[data-career="barista"]');
  await page.waitForTimeout(600);
  console.log('hired', await page.evaluate(() => window.__vita.game.state.career));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);

  // Reopen cafe: work action should exist and be unlocked.
  await page.evaluate(() => window.__vita.game.refreshPrompt());
  await page.keyboard.press('e');
  await page.waitForTimeout(400);
  console.log('cafe actions 2', await page.evaluate(() => [...document.querySelectorAll('[data-action]')].map(b => ({ id: b.dataset.action, disabled: b.disabled, text: b.textContent.trim().slice(0,60) }))));
  const work = page.locator('[data-action="work"]');
  console.log('work count', await work.count(), await work.isEnabled().catch(()=>false));
  if (await work.count()) {
    await work.click();
    await page.waitForTimeout(500);
    console.log('work progress', await page.locator('#progress-title').textContent().catch(()=>null));
    await page.waitForTimeout(1700);
    console.log('after work', await page.evaluate(() => ({ money: window.__vita.game.state.money, career: window.__vita.game.state.career, lastWorkDay: window.__vita.game.state.lastWorkDay, day: window.__vita.game.state.day, progress: !document.querySelector('#progress').hidden })));
  }

  // Relationship flow: chat with a known NPC.
  await page.evaluate(() => {
    const g = window.__vita.game;
    const npc = Object.keys(g.state.relationships)[0];
    g.state.relationships[npc].met = true;
    g.state.relationships[npc].friendship = 30;
    g.state.relationships[npc].romance = 10;
  });
  await page.click('#btn-relations');
  await page.waitForTimeout(400);
  console.log('relations title', await page.locator('#modal-title').textContent());
  const enabled = await page.evaluate(() => [...document.querySelectorAll('[data-rel]')].filter(b => !b.disabled).slice(0,3).map(b => ({rel:b.dataset.rel,npc:b.dataset.npc})));
  console.log('enabled rel', enabled);
  await page.locator('[data-rel="chat"]').first().click();
  await page.waitForTimeout(350);
  console.log('chat progress', await page.locator('#progress-title').textContent().catch(()=>null));
  await page.waitForTimeout(1500);
  console.log('after chat', await page.evaluate(() => ({ social: window.__vita.game.state.needs.social, rels: Object.values(window.__vita.game.state.relationships).filter(r=>r.met).map(r=>r.friendship) })));

  // Save/continue sanity
  await page.evaluate(() => window.__vita.game.save(true));
  await page.waitForTimeout(300);
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('vita.save.v1')));
  console.log('saved', { name: saved.name, money: saved.money, career: saved.career?.id, day: saved.day, dlc: saved.dlc.mare });
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1800);
  console.log('menu continue', await page.evaluate(() => ({ visible: !document.querySelector('#btn-continue').hidden, info: document.querySelector('#save-info').textContent })));
  await page.click('#btn-continue');
  await page.waitForTimeout(1200);
  console.log('continued', await page.evaluate(() => ({ active: window.__vita.game.active, name: window.__vita.game.state.name, career: window.__vita.game.state.career?.id, game: !document.querySelector('#game').hidden })));
  console.log('ERRORS', errors.join('\n') || 'none');
  await browser.close();
})();

