  await page.evaluate(() => { const g = window.__vita.game; g.doRel('wedding', g.state.engagedTo); });
  await page.waitForTimeout(1700);
  console.log('after wedding', await page.evaluate(() => ({ married: window.__vita.game.state.marriedTo, engaged: window.__vita.game.state.engagedTo, money: window.__vita.game.state.money })));

  // Quick DLC zone actions smoke test (open spot and close).
  const spots = ['vineyard','colosseum','canal','beach','boutique','garden'];
